'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var FIFO = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof FIFO, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is an `every` method for returning boolean indicating whether all elements pass a test', function test( t ) {
	t.strictEqual( hasOwnProp( FIFO.prototype, 'every' ), true, 'has property' );
	t.strictEqual( isFunction( FIFO.prototype.every ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a FIFO instance', function test( t ) {
	var values;
	var queue;
	var i;

	queue = new FIFO();
	queue.push( 'foo' );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return queue.every.call( value, predicate );
		};
	}

	function predicate( v ) {
		return v === 'foo';
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var queue;
	var i;

	queue = new FIFO();
	queue.push( 'foo' );
	queue.push( 'bar' );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return queue.every( value );
		};
	}
});

tape( 'the method returns `true` if operating on an empty queue', function test( t ) {
	var bool;
	var queue;

	queue = new FIFO();
	bool = queue.every( predicate );

	t.strictEqual( bool, true, 'returns expected value (vacuous truth)' );
	t.end();

	function predicate() {
		t.fail( 'should not be invoked' );
	}
});

tape( 'the method returns `true` if all elements pass a test', function test( t ) {
	var bool;
	var queue;

	queue = new FIFO();
	queue.push( 2 );
	queue.push( 4 );
	queue.push( 6 );
	queue.push( 8 );

	bool = queue.every( predicate );

	t.strictEqual( bool, true, 'returns expected value' );
	t.end();

	function predicate( v ) {
		return v % 2 === 0;
	}
});

tape( 'the method returns `false` if one or more elements fail a test', function test( t ) {
	var bool;
	var queue;

	queue = new FIFO();
	queue.push( 2 );
	queue.push( 4 );
	queue.push( 5 );
	queue.push( 8 );

	bool = queue.every( predicate );

	t.strictEqual( bool, false, 'returns expected value' );
	t.end();

	function predicate( v ) {
		return v % 2 === 0;
	}
});

tape( 'the method returns `false` on first element that fails the test', function test( t ) {
	var bool;
	var queue;
	var count;

	queue = new FIFO();
	queue.push( 2 );
	queue.push( 4 );
	queue.push( 5 );
	queue.push( 8 );
	queue.push( 10 );

	count = 0;
	bool = queue.every( predicate );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( count, 3, 'invoked correct number of times (short-circuit)' );
	t.end();

	function predicate( v ) {
		count += 1;
		return v % 2 === 0;
	}
});

tape( 'the method supports providing an execution context', function test( t ) {
	var bool;
	var ctx;
	var queue;

	ctx = {
		'count': 0
	};
	queue = new FIFO();
	queue.push( 1 );
	queue.push( 2 );
	queue.push( 3 );
	queue.push( 4 );

	bool = queue.every( predicate, ctx );

	t.strictEqual( bool, true, 'returns expected value' );
	t.strictEqual( ctx.count, 4, 'returns expected context count' );

	t.end();

	function predicate( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return v > 0;
	}
});

tape( 'the method provides the element value, index, and queue as arguments to the predicate', function test( t ) {
	var queue;
	var indices;
	var values;

	queue = new FIFO();
	queue.push( 'a' );
	queue.push( 'b' );
	queue.push( 'c' );

	values = [];
	indices = [];

	queue.every( predicate );

	t.deepEqual( values, [ 'a', 'b', 'c' ], 'passes element values' );
	t.deepEqual( indices, [ 0, 1, 2 ], 'passes indices' );

	t.end();

	function predicate( v, i, q ) {
		values.push( v );
		indices.push( i );
		t.strictEqual( q, queue, 'passes queue as third argument' );
		return true;
	}
});

tape( 'the method works with different data types', function test( t ) {
	var bool;
	var queue;

	queue = new FIFO();
	queue.push( 0 );
	queue.push( 1 );
	queue.push( 2 );

	bool = queue.every( function( v ) {
		return typeof v === 'number';
	});

	t.strictEqual( bool, true, 'works with numbers' );

	queue = new FIFO();
	queue.push( 'foo' );
	queue.push( 'bar' );
	queue.push( 'baz' );

	bool = queue.every( function( v ) {
		return typeof v === 'string';
	});

	t.strictEqual( bool, true, 'works with strings' );

	queue = new FIFO();
	queue.push( true );
	queue.push( false );
	queue.push( true );

	bool = queue.every( function( v ) {
		return typeof v === 'boolean';
	});

	t.strictEqual( bool, true, 'works with booleans' );

	t.end();
});
